Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_prepend_resize_failure(void) {
    // Setup: create a buffer with small size and some content
    // The buffer must be too small to hold the prepended string, so resize is needed
    // We want buffer_resize to fail (simulate realloc failure)
    // helper_create_buffer_with_content allocates 2 times (buffer_new_with_copy)
    buffer_t *buf = helper_create_buffer_with_content("world");
    TEST_ASSERT_NOT_NULL(buf);

    // Now, fail the next allocation (the realloc in buffer_resize)
    malloc_fail_after(2); // 2 allocations for setup, fail the 3rd (resize)

    // Prepend a string that will require resizing
    int ret = buffer_prepend(buf, "hello ");

    // Assert: should return -1 due to resize failure, buffer content unchanged
    TEST_ASSERT_EQUAL_INT(-1, ret);
    helper_assert_buffer_content(buf, "world");

    // Cleanup
    helper_free_buffer(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_prepend_resize_failure);
    return UNITY_END();
}


